using System.ComponentModel;
using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool implementations ---
var notebook = new Notebook();

var tools = new[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for a query and returns a list of result snippets with titles and URLs."),

    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Content of the note")] string content) => notebook.AddNote(title, content),
        "add_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () => notebook.GetNotes(),
        "get_notes",
        "Retrieves all research notes saved so far."),

    AIFunctionFactory.Create(
        ([Description("URL to fetch content from")] string url) => WebSearchTool.FetchPageAsync(url),
        "fetch_page",
        "Fetches the text content of a web page given its URL."),
};

// --- Build the AI chat client with automatic tool invocation ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// --- Determine research topic ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent             ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
}

Console.WriteLine($"\nResearching: {topic}\n");

var systemPrompt = $$"""
    You are a research agent. Your goal is to thoroughly research the topic provided by the user.

    Follow this workflow:
    1. Search the web for the topic using several varied queries (at least 2-3 different angles).
    2. Fetch the most promising pages to get detailed information.
    3. Save key findings as notes using the add_note tool.
    4. After gathering enough information, retrieve your notes and produce a final summary.

    Be thorough but concise. Always cite sources with URLs.
    When you are done, output a well-structured final summary with sections and source links.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic: {topic}")
};

// --- Agent loop ---
Console.WriteLine("Agent is working...\n");

var response = await client.GetResponseAsync(messages, chatOptions);
Console.WriteLine(response.Text);

// --- Tool classes ---

static partial class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
            { "Accept", "text/html" }
        },
        Timeout = TimeSpan.FromSeconds(15)
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = new List<object>();
            foreach (Match m in ResultPattern().Matches(html))
            {
                if (results.Count >= 8) break;

                var href = WebUtility.HtmlDecode(m.Groups[1].Value);
                var title = StripHtml(WebUtility.HtmlDecode(m.Groups[2].Value));
                var snippet = StripHtml(WebUtility.HtmlDecode(m.Groups[3].Value));

                if (href.Contains("duckduckgo.com")) continue;

                results.Add(new { title, url = href, snippet });
            }

            return results.Count > 0
                ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    public static async Task<string> FetchPageAsync(string url)
    {
        Console.WriteLine($"  🌐 Fetching: {url}");
        try
        {
            var html = await Http.GetStringAsync(url);

            // Strip scripts, styles, and tags to get plain text
            html = ScriptStylePattern().Replace(html, " ");
            var text = StripHtml(html);

            // Collapse whitespace
            text = WhitespacePattern().Replace(text, " ").Trim();

            // Limit length
            return text.Length > 5000 ? text[..5000] + "\n...[truncated]" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static string StripHtml(string html) => HtmlTagPattern().Replace(html, "");

    [GeneratedRegex("""<a[^>]+href="([^"]*)"[^>]*class="result__a"[^>]*>(.*?)</a>.*?<a[^>]+class="result__snippet"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
