class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public string AddNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        Console.WriteLine($"  📝 Note saved: {title}");
        return $"Note '{title}' saved successfully. You now have {_notes.Count} note(s).";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var result = _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}");
        return string.Join("\n\n", result);
    }
}

